"use strict";(self.webpackChunkgf_site=self.webpackChunkgf_site||[]).push([["1924"],{55226(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"0.2.x(Latest)","banner":null,"badge":true,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"quickSidebar":[{"type":"link","href":"/quick/overview","label":"Project Overview","docId":"quick/overview","unlisted":false},{"type":"link","href":"/quick/environment","label":"Environment Setup","docId":"quick/environment","unlisted":false},{"type":"link","href":"/quick/installation","label":"Installation","docId":"quick/installation","unlisted":false},{"type":"link","href":"/quick/have-a-try","label":"Try It Out","docId":"quick/have-a-try","unlisted":false}],"docsSidebar":[{"type":"category","label":"Design Principles","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/ai-native","label":"AI-Native Design","docId":"docs/concepts/ai-native","unlisted":false},{"type":"link","href":"/docs/modular-design","label":"Modular Design","docId":"docs/concepts/modular-design","unlisted":false},{"type":"link","href":"/docs/spec-driven-development","label":"AI Spec-Driven Development","docId":"docs/concepts/spec-driven-development","unlisted":false}],"href":"/docs/concepts"},{"type":"category","label":"Component Design","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/core-host","label":"Core Host Service","docId":"docs/components/core-host","unlisted":false},{"type":"link","href":"/docs/admin-workspace","label":"Built-in Admin Workspace","docId":"docs/components/admin-workspace","unlisted":false},{"type":"category","label":"Dual-Mode Plugin System","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/source-plugins","label":"Source Plugins","docId":"docs/components/plugin-system/source-plugins","unlisted":false},{"type":"link","href":"/docs/wasm-plugins","label":"Dynamic Plugins (WASM)","docId":"docs/components/plugin-system/wasm-plugins","unlisted":false},{"type":"link","href":"/docs/plugin-management","label":"Plugin Management","docId":"docs/components/plugin-system/plugin-management","unlisted":false}],"href":"/docs/plugin-system"},{"type":"link","href":"/docs/distributed-architecture","label":"Native Distributed Architecture","docId":"docs/components/distributed-architecture","unlisted":false},{"type":"link","href":"/docs/configuration","label":"Service Configuration","docId":"docs/components/configuration","unlisted":false},{"type":"link","href":"/docs/api-reference","label":"OpenAPI Reference","docId":"docs/components/api-reference","unlisted":false},{"type":"link","href":"/docs/multi-tenant","label":"Native Multi-Tenancy","docId":"docs/components/multi-tenant","unlisted":false},{"type":"link","href":"/docs/cron-tasks","label":"Scheduled Tasks","docId":"docs/components/cron-tasks","unlisted":false},{"type":"link","href":"/docs/i18n","label":"Framework-Level Internationalization","docId":"docs/components/i18n","unlisted":false}],"href":"/docs/components"},{"type":"category","label":"Development Tools","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/docs/commands","label":"Development Commands","docId":"docs/tools/commands","unlisted":false},{"type":"link","href":"/docs/agent-skills","label":"Agent Skills","docId":"docs/tools/agent-skills","unlisted":false}],"href":"/docs/tools"}],"communitySidebar":[{"type":"link","href":"/community","label":"Community","docId":"community/community","unlisted":false},{"type":"link","href":"/community/support","label":"Support Us","docId":"community/support","unlisted":false}]},"docs":{"community/community":{"id":"community/community","title":"Community","description":"Official LinaPro community channels \u2014 QQ groups, WeChat, Discord, and GitHub Issues \u2014 with guidance on which channel is best for real-time discussion, reproducible bugs, feature requests, documentation feedback, and plugin development questions.","sidebar":"communitySidebar"},"community/support":{"id":"community/support","title":"Support Us","description":"Practical ways to support the long-term maintenance of LinaPro, including filing reproducible issues, improving documentation, sharing production experience, joining community discussions, and donating through WeChat Pay or Alipay. Please include your GitHub or Gitee account name in the donation note so we can keep an accurate donation record.","sidebar":"communitySidebar"},"docs/components/admin-workspace":{"id":"docs/components/admin-workspace","title":"Built-in Admin Workspace","description":"A component-level guide to the LinaPro built-in admin workspace, lina-vben \u2014 how it serves as the standard frontend consumer of the core host service and plugin system, covering access control, system settings, job scheduling, multi-tenant management, plugin governance, developer center, and dynamic plugin pages, while maintaining consistency with backend API contracts, menu permissions, and I18N resources.","sidebar":"docsSidebar"},"docs/components/api-reference":{"id":"docs/components/api-reference","title":"OpenAPI Reference","description":"From a component design perspective, this page explains how LinaPro aggregates API documentation \u2014 the core host, source plugins, and WASM dynamic plugins are unified into a single OpenAPI document through g.Meta contracts, permission tags, API doc i18n resources, the in-workspace developer center debugging page, and third-party tool import.","sidebar":"docsSidebar"},"docs/components/components":{"id":"docs/components/components","title":"Component Design","description":"An overview of LinaPro framework components \u2014 the core host service, built-in admin workspace, dual-mode plugin system, source plugins, WASM dynamic plugins, plugin management, native distributed architecture, and host capabilities including configuration, API documentation, multi-tenancy, scheduled tasks, and I18N internationalization.","sidebar":"docsSidebar"},"docs/components/configuration":{"id":"docs/components/configuration","title":"Service Configuration","description":"A component-level guide to LinaPro core host service configuration \u2014 how config.yaml drives HTTP server, logging, database, JWT authentication, sessions, monitoring, health probes, scheduling, internationalization, cluster coordination, file uploads, and plugin governance, with production deployment recommendations.","sidebar":"docsSidebar"},"docs/components/core-host":{"id":"docs/components/core-host","title":"Core Host Service","description":"A component-level guide to the LinaPro core host service lina-core \u2014 covering API contracts, governance services, runtime configuration, API documentation aggregation, scheduling, internationalization, multi-tenant foundation, plugin runtime, cluster coordination, and health probes, and how the host serves as a stable foundation for the workspace, source plugins, and WASM dynamic plugins.","sidebar":"docsSidebar"},"docs/components/cron-tasks":{"id":"docs/components/cron-tasks","title":"Scheduled Tasks","description":"A component-level guide to the LinaPro persistent scheduled task system \u2014 task types, cron expressions, task groups, execution logs, built-in tasks, source plugin and dynamic plugin task declarations, master_only and all_node execution scopes, singleton and parallel concurrency strategies, and cluster scheduling behavior.","sidebar":"docsSidebar"},"docs/components/distributed-architecture":{"id":"docs/components/distributed-architecture","title":"Native Distributed Architecture","description":"From a component design perspective, this page explains the native distributed architecture of LinaPro \u2014 how to switch between single-node and cluster mode, the Redis coordinator, leader election, node responsibilities, cache revision, distributed locks, key-value cache, scheduled task execution scope, and the horizontal scaling process \u2014 helping developers understand how business code can scale to multi-node deployment with zero modifications.","sidebar":"docsSidebar"},"docs/components/i18n":{"id":"docs/components/i18n","title":"Framework-Level Internationalization","description":"A component-level guide to the LinaPro I18N internationalization runtime \u2014 how host language packs, plugin language packs, dynamic plugin language resources, API documentation translations, runtime caching, locale configuration, and frontend language switching work together, and what resource boundaries teams must maintain when adding new languages.","sidebar":"docsSidebar"},"docs/components/multi-tenant":{"id":"docs/components/multi-tenant","title":"Native Multi-Tenancy","description":"A component-level guide to LinaPro multi-tenancy \u2014 how the host bizctx, TenantFilterService, tenant_id filtering seam, default platform tenant, official multi-tenant source plugin, tenant impersonation, plugin multi-tenant manifest fields, and the current Pool shared-database model work together.","sidebar":"docsSidebar"},"docs/components/plugin-system/plugin-management":{"id":"docs/components/plugin-system/plugin-management","title":"Plugin Management","description":"From a component design and operational flow perspective, this page explains LinaPro plugin management \u2014 plugin source configuration, the local plugin workspace, plugins.init, plugins.install, plugins.update, plugins.status, admin workspace installation and enablement, disablement and uninstallation, dynamic plugin upload, and runtime upgrade \u2014 covering the full chain from code acquisition to runtime activation.","sidebar":"docsSidebar"},"docs/components/plugin-system/plugin-system":{"id":"docs/components/plugin-system/plugin-system","title":"Dual-Mode Plugin System","description":"A component-level guide to the LinaPro dual-mode plugin system \u2014 why source plugins and WASM dynamic plugins share the same governance pipeline, and how catalog, dependency, lifecycle, integration, plugin-runtime cache, pluginhost, pluginbridge, plugin.yaml, multi-tenant fields, lifecycle states, isolation mechanisms, and runtime upgrades together form an extensible plugin architecture.","sidebar":"docsSidebar"},"docs/components/plugin-system/source-plugins":{"id":"docs/components/plugin-system/source-plugins","title":"Source Plugins","description":"A component-level and developer-practice guide to LinaPro source plugins \u2014 use cases, directory structure, plugin.yaml manifest, installation SQL, API contracts, service layer implementation, pluginhost registration, database access, frontend pages, event hooks, runtime upgrades, and best practices for extending long-term business capabilities with native Go.","sidebar":"docsSidebar"},"docs/components/plugin-system/wasm-plugins":{"id":"docs/components/plugin-system/wasm-plugins","title":"Dynamic Plugins (WASM)","description":"An introduction to WebAssembly (WASM) fundamentals and advantages \u2014 cross-platform support, secure sandboxing, near-native performance, hot-loading, and multi-language ecosystem \u2014 followed by a practical guide to LinaPro WASM dynamic plugins covering use cases, sandbox model, pluginbridge protocol, exported functions, hostServices authorization, build process, runtime installation and enablement, explicit upgrades, and key differences from source plugins.","sidebar":"docsSidebar"},"docs/concepts/ai-native":{"id":"docs/concepts/ai-native","title":"AI-Native Design","description":"A detailed look at LinaPro as an AI-native framework \u2014 what AI-native truly means, how it differs from AI-assisted development, how AI participates in every stage of the development lifecycle, the built-in AI skill system covering backend, frontend, testing, performance auditing, and version management, and why spec-driven development prevents architectural drift over time.","sidebar":"docsSidebar"},"docs/concepts/concepts":{"id":"docs/concepts/concepts","title":"Design Principles","description":"An introduction to the core design principles behind LinaPro \u2014 AI-native design, modular architecture, and AI spec-driven development \u2014 helping developers build the right mental model before going deeper into the framework.","sidebar":"docsSidebar"},"docs/concepts/modular-design":{"id":"docs/concepts/modular-design","title":"Modular Design","description":"An exploration of LinaPro modular design \u2014 how domain-bounded built-in capabilities, first-class plugin system, stable extension seams, and lifecycle-managed modules let developers assemble systems from proven building blocks rather than building everything from scratch.","sidebar":"docsSidebar"},"docs/concepts/spec-driven-development":{"id":"docs/concepts/spec-driven-development","title":"AI Spec-Driven Development","description":"A detailed guide to LinaPro Specification-Driven Development (SDD) and the OpenSpec workflow \u2014 the five-stage development loop (explore, propose, implement, review, archive), the responsibilities of AI and humans at each stage, the OpenSpec directory structure and spec file formats, and how spec anchors and mandatory E2E tests prevent architectural drift.","sidebar":"docsSidebar"},"docs/tools/agent-skills":{"id":"docs/tools/agent-skills","title":"Agent Skills","description":"A complete guide to LinaPro AI skills \u2014 the optional OpenSpec CLI, goframe-v2, and find-skills that can be installed externally, plus project-bundled skills covering frontend design, Git workflows, code review, E2E testing, performance auditing, and OpenSpec apply/archive automation. Includes installation instructions and usage guidance for every skill.","sidebar":"docsSidebar"},"docs/tools/commands":{"id":"docs/tools/commands","title":"Development Commands","description":"A complete reference for the cross-platform development command set in the LinaPro project \u2014 covering linactl, Makefile compatibility entry, Windows make.cmd wrapper, development server management, full builds, WASM plugin builds, Docker image builds, plugin workspace management, testing, i18n validation, database initialization, and release governance on macOS, Linux, and Windows.","sidebar":"docsSidebar"},"docs/tools/tools":{"id":"docs/tools/tools","title":"Development Tools","description":"An overview of the developer tooling built into LinaPro \u2014 covering every make command with usage examples, and the full AI skills library for frontend design, code review, testing, performance auditing, and OpenSpec workflows.","sidebar":"docsSidebar"},"quick/environment":{"id":"quick/environment","title":"Environment Setup","description":"This guide covers every environment dependency required to run LinaPro from source, including Git, Go (>= 1.23), Node.js (>= 20.19), pnpm (>= 10.0), PostgreSQL (14+), Make, and the recommended AI-native workflow tools Claude Code, OpenSpec CLI, and the goframe-v2 skill. It also provides installation guidance for macOS, Linux, and Windows (WSL / Git Bash) so you can prepare your local machine before installing LinaPro.","sidebar":"quickSidebar"},"quick/have-a-try":{"id":"quick/have-a-try","title":"Try It Out","description":"This guide walks through a complete article management CRUD source plugin example to demonstrate LinaPro\'s AI-native development flow, including requirement exploration with the spec-driven workflow, proposal generation, AI-driven implementation, service startup and functional verification, and change archival. It helps developers experience the core development model of an AI-native framework.","sidebar":"quickSidebar"},"quick/installation":{"id":"quick/installation","title":"Installation","description":"How to install and initialize LinaPro in a few minutes \u2014 cloning the repository, configuring the database connection, initializing the database schema, loading demo data, and starting the development service. Complete the environment setup before cloning.","sidebar":"quickSidebar"},"quick/overview":{"id":"quick/overview","title":"Project Overview","description":"A comprehensive introduction to LinaPro \u2014 its background, architecture, and core capabilities. LinaPro is an AI-native full-stack framework built on Go + Vue 3 with PostgreSQL by default (optional SQLite), native multi-tenant support, an official plugin submodule, Redis cluster coordination, a dual-mode plugin system, RBAC permission management, scheduled task scheduling, live API documentation, the optional-but-recommended OpenSpec spec-driven AI development workflow, and a lifecycle-spanning AI skill set for building sustainable, continuously deliverable business systems.","sidebar":"quickSidebar"}}}}')}}]);